/**
 * RecordSearchService
 *
 * Backend for the "record finder" Lightning component.
 *
 * search(...) builds and runs exactly one SOQL query:
 *   SELECT Id, <fields> FROM <object>
 *   [WHERE field = :bind (AND field = :bind)*]
 *   [ORDER BY <orderByField> ASC]
 *   LIMIT <maxRows>
 *
 * All names (object, fields, filter keys, order by) are resolved against the
 * object's describe, so the SOQL text is always built from validated,
 * canonical metadata names.  Filter values are passed as bind variables, so
 * user supplied values can never be interpreted as SOQL.
 *
 * Row visibility is enforced by `with sharing` (record sharing) and the query
 * is executed in user mode (object + field level security).  Any problem is
 * surfaced as RecordSearchService.SearchException - never a system exception.
 */
public with sharing class RecordSearchService {

    /** Single exception type thrown by RecordSearchService. */
    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;
    private static final String ID_FIELD = 'Id';

    /**
     * Searches records of `objectApiName`.
     *
     * @param objectApiName API name of the object (case-insensitive).
     * @param fields        API names of the fields to return (case-insensitive). Id is always returned.
     * @param filters       Optional equality filters: field API name => value (null allowed).
     * @param orderByField  Optional field API name to order by (ascending). Blank = no ordering.
     * @param maxRows       1..200.
     * @return List of SObjects.
     * @throws SearchException for every invalid input or access problem.
     */
    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        try {
            return runSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            // Never let a system exception escape: normalise everything to SearchException.
            throw new SearchException(e.getMessage());
        }
    }

    private static List<SObject> runSearch(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {

        // ------------------------------------------------------------------
        // 1. Input validation
        // ------------------------------------------------------------------
        if (maxRows == null) {
            throw new SearchException('maxRows is required.');
        }
        if (maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }

        // ------------------------------------------------------------------
        // 2. Resolve the object (case-insensitive) and check access
        // ------------------------------------------------------------------
        Schema.SObjectType objectType = Schema.getGlobalDescribe().get(objectApiName.trim().toLowerCase());
        if (objectType == null) {
            throw new SearchException('Unknown object: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
        if (!objectDescribe.isAccessible() || !objectDescribe.isQueryable()) {
            throw new SearchException('No read access to object ' + objectDescribe.getName() + '.');
        }

        // Case-insensitive field lookup table built from the object describe.
        Map<String, Schema.SObjectField> fieldsByName = new Map<String, Schema.SObjectField>();
        Map<String, Schema.SObjectField> describedFields = objectDescribe.fields.getMap();
        for (String fieldName : describedFields.keySet()) {
            fieldsByName.put(fieldName.toLowerCase(), describedFields.get(fieldName));
        }

        // ------------------------------------------------------------------
        // 3. SELECT clause (Id is always selected and de-duplicated)
        // ------------------------------------------------------------------
        List<String> selectFields = new List<String>{ ID_FIELD };
        Set<String> alreadySelected = new Set<String>{ ID_FIELD.toLowerCase() };

        for (String requestedField : fields) {
            Schema.SObjectField field = resolveField(requestedField, fieldsByName);
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();

            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('No read access to field ' + fieldDescribe.getName() + '.');
            }

            String canonicalName = fieldDescribe.getName();
            if (alreadySelected.add(canonicalName.toLowerCase())) {
                selectFields.add(canonicalName);
            }
        }

        // ------------------------------------------------------------------
        // 4. WHERE clause - one equality condition per filter, ANDed together
        // ------------------------------------------------------------------
        List<String> conditions = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();

        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String filterField : filters.keySet()) {
                Schema.SObjectField field = resolveField(filterField, fieldsByName);
                Schema.DescribeFieldResult fieldDescribe = field.getDescribe();

                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('No read access to field ' + fieldDescribe.getName() + '.');
                }
                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException('Field ' + fieldDescribe.getName() + ' cannot be filtered.');
                }

                String bindName = 'b' + bindIndex;
                bindIndex++;

                conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                binds.put(bindName, coerceValue(filters.get(filterField), fieldDescribe));
            }
        }

        // ------------------------------------------------------------------
        // 5. ORDER BY clause
        // ------------------------------------------------------------------
        String orderClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField field = resolveField(orderByField, fieldsByName);
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();

            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('No read access to field ' + fieldDescribe.getName() + '.');
            }
            if (!fieldDescribe.isSortable()) {
                throw new SearchException('Field ' + fieldDescribe.getName() + ' cannot be sorted.');
            }
            orderClause = ' ORDER BY ' + fieldDescribe.getName() + ' ASC';
        }

        // ------------------------------------------------------------------
        // 6. Build and run the single query
        // ------------------------------------------------------------------
        String soql = 'SELECT ' + String.join(selectFields, ', ')
                    + ' FROM ' + objectDescribe.getName();
        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        soql += orderClause;
        soql += ' LIMIT ' + maxRows;

        List<SObject> records;
        if (binds.isEmpty()) {
            records = Database.query(soql);
        } else {
            // USER_MODE enforces object and field level security for the running user.
            records = Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        }
        return records;
    }

    /**
     * Looks a field up by API name, ignoring case.
     */
    private static Schema.SObjectField resolveField(String fieldName, Map<String, Schema.SObjectField> fieldsByName) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('Field API name is required.');
        }
        Schema.SObjectField field = fieldsByName.get(fieldName.trim().toLowerCase());
        if (field == null) {
            throw new SearchException('Unknown field: ' + fieldName);
        }
        return field;
    }

    /**
     * Normalises UI supplied values so that they can safely be used as a bind
     * variable against a field of the given type (e.g. "5" -> 5, "2024-01-31"
     * -> Date).  Values that already carry the right type are passed through.
     * The value itself never reaches the query text.
     */
    private static Object coerceValue(Object value, Schema.DescribeFieldResult fieldDescribe) {
        if (value == null) {
            return null;
        }
        if (!(value instanceof String)) {
            return value;
        }

        String text = ((String) value).trim();
        if (String.isEmpty(text)) {
            return value;
        }

        Schema.DisplayType fieldType = fieldDescribe.getType();
        try {
            if (fieldType == Schema.DisplayType.INTEGER || fieldType == Schema.DisplayType.LONG) {
                return Decimal.valueOf(text);
            }
            if (fieldType == Schema.DisplayType.DOUBLE
                    || fieldType == Schema.DisplayType.CURRENCY
                    || fieldType == Schema.DisplayType.PERCENT) {
                return Decimal.valueOf(text);
            }
            if (fieldType == Schema.DisplayType.BOOLEAN) {
                if (text.equalsIgnoreCase('true')) {
                    return true;
                }
                if (text.equalsIgnoreCase('false')) {
                    return false;
                }
                throw new SearchException('Invalid value "' + text + '" for field ' + fieldDescribe.getName() + '.');
            }
            if (fieldType == Schema.DisplayType.DATE) {
                return Date.valueOf(text);
            }
            if (fieldType == Schema.DisplayType.DATETIME) {
                try {
                    return Datetime.valueOf(text);
                } catch (Exception e) {
                    // Allow a plain date for a date/time field.
                    return Date.valueOf(text);
                }
            }
            if (fieldType == Schema.DisplayType.ID || fieldType == Schema.DisplayType.REFERENCE) {
                return Id.valueOf(text);
            }
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException('Invalid value "' + text + '" for field ' + fieldDescribe.getName() + '.');
        }

        return value;
    }
}
