@IsTest
private class AddressVerificationServiceTest {

    private class MockCallout implements HttpCalloutMock {
        public HttpResponse response;
        public HttpRequest request;
        public Integer callCount = 0;

        public HttpResponse respond(HttpRequest req) {
            request = req;
            callCount++;
            return response;
        }
    }

    private static MockCallout mockCallout(Integer statusCode, String body) {
        MockCallout mock = new MockCallout();
        HttpResponse res = new HttpResponse();
        res.setStatusCode(statusCode);
        res.setBody(body);
        mock.response = res;
        return mock;
    }

    private static Account newAccount() {
        return new Account(
            Name = 'Test Account',
            BillingStreet = '1 Old Street',
            BillingCity = 'Old City',
            BillingPostalCode = '00000',
            BillingCountry = 'Old Country'
        );
    }

    @IsTest
    static void blankBillingStreetIsSkippedWithoutCallout() {
        MockCallout mock = mockCallout(
            200,
            '{"status":"CORRECTED","address":{"street":"1 New Street","city":"New City","postalCode":"99999","country":"New Country"}}'
        );
        Test.setMock(HttpCalloutMock.class, mock);

        Account whitespace = newAccount();
        whitespace.BillingStreet = '   ';
        AddressVerificationService.Result whitespaceResult = AddressVerificationService.verify(whitespace);
        System.assertEquals('SKIPPED', whitespaceResult.status);
        System.assertEquals(false, whitespaceResult.changed);
        System.assertEquals(0, mock.callCount, 'Whitespace BillingStreet must not make a callout.');
        System.assertEquals('   ', whitespace.BillingStreet);

        Account nullStreet = newAccount();
        nullStreet.BillingStreet = null;
        AddressVerificationService.Result nullResult = AddressVerificationService.verify(nullStreet);
        System.assertEquals('SKIPPED', nullResult.status);
        System.assertEquals(false, nullResult.changed);
        System.assertEquals(0, mock.callCount, 'Null BillingStreet must not make a callout.');
        System.assertEquals(null, nullStreet.BillingStreet);
    }

    @IsTest
    static void requestMatchesApiContract() {
        Account acct = new Account(
            Name = 'Request Account',
            BillingStreet = '123 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'USA'
        );
        MockCallout mock = mockCallout(
            200,
            '{"status":"VERIFIED","address":{"street":"different","city":"different","postalCode":"different","country":"different"}}'
        );
        Test.setMock(HttpCalloutMock.class, mock);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('VERIFIED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(1, mock.callCount, 'Exactly one callout was expected.');
        System.assertNotEquals(null, mock.request, 'A request should have been sent.');
        System.assertEquals('callout:FB_Address_API/v2/verify', mock.request.getEndpoint());
        System.assertEquals('POST', mock.request.getMethod());
        System.assertEquals('application/json', mock.request.getHeader('Content-Type'));

        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(mock.request.getBody());
        System.assertEquals(4, body.size(), 'Body must contain exactly the four documented fields.');
        System.assertEquals('123 Main St', body.get('street'));
        System.assertEquals('Springfield', body.get('city'));
        System.assertEquals('12345', body.get('postalCode'));
        System.assertEquals('USA', body.get('country'));

        System.assertEquals('123 Main St', acct.BillingStreet);
        System.assertEquals('Springfield', acct.BillingCity);
        System.assertEquals('12345', acct.BillingPostalCode);
        System.assertEquals('USA', acct.BillingCountry);
    }

    @IsTest
    static void non200ResponsesThrowExceptionContainingStatusCode() {
        Account acct = newAccount();

        for (Integer statusCode : new List<Integer>{201, 400, 500}) {
            MockCallout mock = mockCallout(statusCode, 'this is not valid json');
            Test.setMock(HttpCalloutMock.class, mock);

            Boolean thrown = false;
            try {
                AddressVerificationService.verify(acct);
            } catch (AddressVerificationService.AddressVerificationException e) {
                thrown = true;
                System.assert(
                    e.getMessage().contains(String.valueOf(statusCode)),
                    'Exception message should contain HTTP status ' + statusCode + ', was: ' + e.getMessage()
                );
            }

            System.assertEquals(true, thrown, 'HTTP ' + statusCode + ' should throw AddressVerificationException.');
            System.assertEquals(1, mock.callCount, 'One callout expected for HTTP ' + statusCode + '.');
            System.assertEquals('1 Old Street', acct.BillingStreet);
            System.assertEquals('Old City', acct.BillingCity);
            System.assertEquals('00000', acct.BillingPostalCode);
            System.assertEquals('Old Country', acct.BillingCountry);
        }
    }

    @IsTest
    static void verifiedResponseLeavesAccountUntouched() {
        Account acct = newAccount();
        MockCallout mock = mockCallout(
            200,
            '{"status":"VERIFIED","address":{"street":"9 New St","city":"New City","postalCode":"99999","country":"New Country"}}'
        );
        Test.setMock(HttpCalloutMock.class, mock);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('VERIFIED', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(1, mock.callCount);
        System.assertEquals('1 Old Street', acct.BillingStreet);
        System.assertEquals('Old City', acct.BillingCity);
        System.assertEquals('00000', acct.BillingPostalCode);
        System.assertEquals('Old Country', acct.BillingCountry);
    }

    @IsTest
    static void invalidResponseLeavesAccountUntouched() {
        Account acct = newAccount();
        MockCallout mock = mockCallout(
            200,
            '{"status":"INVALID","address":{"street":"9 New St","city":"New City","postalCode":"99999","country":"New Country"}}'
        );
        Test.setMock(HttpCalloutMock.class, mock);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('INVALID', result.status);
        System.assertEquals(false, result.changed);
        System.assertEquals(1, mock.callCount);
        System.assertEquals('1 Old Street', acct.BillingStreet);
        System.assertEquals('Old City', acct.BillingCity);
        System.assertEquals('00000', acct.BillingPostalCode);
        System.assertEquals('Old Country', acct.BillingCountry);
    }

    @IsTest
    static void correctedResponseOverwritesAllBillingFields() {
        Account acct = newAccount();
        MockCallout mock = mockCallout(
            200,
            '{"status":"CORRECTED","address":{"street":"9 New St","city":"New City","postalCode":"99999","country":"New Country"}}'
        );
        Test.setMock(HttpCalloutMock.class, mock);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('CORRECTED', result.status);
        System.assertEquals(true, result.changed);
        System.assertEquals('9 New St', acct.BillingStreet);
        System.assertEquals('New City', acct.BillingCity);
        System.assertEquals('99999', acct.BillingPostalCode);
        System.assertEquals('New Country', acct.BillingCountry);
        System.assertEquals(1, mock.callCount);
    }

    @IsTest
    static void correctedStatusIsHandledCaseInsensitively() {
        Account acct = newAccount();
        MockCallout mock = mockCallout(
            200,
            '{"status":"corrected","address":{"street":"9 New St","city":"New City","postalCode":"99999","country":"New Country"}}'
        );
        Test.setMock(HttpCalloutMock.class, mock);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('corrected', result.status);
        System.assertEquals(true, result.changed);
        System.assertEquals('9 New St', acct.BillingStreet);
        System.assertEquals('New City', acct.BillingCity);
        System.assertEquals('99999', acct.BillingPostalCode);
        System.assertEquals('New Country', acct.BillingCountry);
    }

    @IsTest
    static void mixedCaseCorrectedResponseOverwritesAllBillingFields() {
        Account acct = newAccount();
        MockCallout mock = mockCallout(
            200,
            '{"status":"Corrected","address":{"street":"9 New St","city":"New City","postalCode":"99999","country":"New Country"}}'
        );
        Test.setMock(HttpCalloutMock.class, mock);

        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('Corrected', result.status);
        System.assertEquals(true, result.changed);
        System.assertEquals('9 New St', acct.BillingStreet);
        System.assertEquals('New City', acct.BillingCity);
        System.assertEquals('99999', acct.BillingPostalCode);
        System.assertEquals('New Country', acct.BillingCountry);
    }
}
