@isTest
private class OpportunityWonHandlerTest {
    private static final String WON = 'Closed Won';
    private static final String HANDOVER = 'Handover to Customer Success';
    private static final String KICKOFF = 'Customer kick-off';

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Account makeAccount(String name, String rating) {
        Account a = new Account(Name = name, Rating = rating);
        insert a;
        return a;
    }

    private static Opportunity makeOpp(String name, String stage, Date closeDate, Id accountId) {
        return new Opportunity(
            Name = name,
            StageName = stage,
            CloseDate = closeDate,
            AccountId = accountId
        );
    }

    private static Set<Id> idsOf(List<Opportunity> opps) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity o : opps) {
            ids.add(o.Id);
        }
        return ids;
    }

    private static User makeOtherUser() {
        String uname = 'testowner'
            + String.valueOf(DateTime.now().getTime())
            + String.valueOf(Math.abs(Crypto.getRandomInteger()))
            + String.valueOf(UserInfo.getUserId())
            + '@example.com';

        User u = new User(
            FirstName = 'Test',
            LastName = 'Owner',
            Email = uname,
            Username = uname,
            Alias = 'towner',
            TimeZoneSidKey = 'America/Los_Angeles',
            LocaleSidKey = 'en_US',
            EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US',
            ProfileId = UserInfo.getProfileId(),
            IsActive = true
        );
        insert u;
        return u;
    }

    private static void assertTaskFields(Task t, Id oppId, Id ownerId, Date expectedActivityDate) {
        System.assertEquals(KICKOFF, t.Subject, 'Task subject must be ' + KICKOFF);
        System.assertEquals(oppId, t.WhatId, 'Task must be attached to the opportunity');
        System.assertEquals(ownerId, t.OwnerId, 'Task owner must be the opportunity owner');
        System.assertEquals(expectedActivityDate, t.ActivityDate, 'Task activity date must be CloseDate + 7 days');
        System.assertEquals('High', t.Priority, 'Task priority must be High');
    }

    // ---------------------------------------------------------------------
    // Insert as won
    // ---------------------------------------------------------------------

    @isTest
    static void insertWonSetsNextStepCreatesTaskAndRatesAccount() {
        Account a = makeAccount('Insert Won Account', 'Warm');
        Date closeDate = Date.today().addDays(10);
        Opportunity o = makeOpp('Insert Won Opp', WON, closeDate, a.Id);
        o.NextStep = 'Initial';

        Test.startTest();
        insert o;
        Test.stopTest();

        Opportunity saved = [SELECT Id, NextStep, OwnerId, CloseDate, AccountId FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(HANDOVER, saved.NextStep, 'NextStep must be overwritten before save for a newly won insert');

        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :o.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task must be created for a newly won opportunity');
        assertTaskFields(tasks[0], o.Id, saved.OwnerId, closeDate.addDays(7));

        System.assertEquals('Hot', [SELECT Rating FROM Account WHERE Id = :a.Id].Rating, 'Account rating must become Hot');
    }

    @isTest
    static void insertWonTaskOwnerIsOpportunityOwner() {
        User other = makeOtherUser();
        Account a = makeAccount('Owner Account', 'Warm');
        Opportunity o = makeOpp('Owner Opp', WON, Date.today().addDays(2), a.Id);
        o.OwnerId = other.Id;

        Test.startTest();
        insert o;
        Test.stopTest();

        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :o.Id];
        System.assertEquals(1, tasks.size(), 'Expected exactly one task');
        System.assertEquals(other.Id, tasks[0].OwnerId, 'Task owner must be the opportunity owner, not the running user');
        System.assertEquals(Date.today().addDays(2).addDays(7), tasks[0].ActivityDate, 'Task activity date');
    }

    @isTest
    static void insertWonWithoutAccountStillCreatesTask() {
        Date closeDate = Date.today().addDays(1);
        Opportunity o = makeOpp('No Account Won Opp', WON, closeDate, null);

        Test.startTest();
        insert o;
        Test.stopTest();

        Opportunity saved = [SELECT NextStep FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(HANDOVER, saved.NextStep, 'NextStep must be set even without an account');

        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :o.Id];
        System.assertEquals(1, tasks.size(), 'A won opportunity without an account must still get a task');
        assertTaskFields(tasks[0], o.Id, o.OwnerId, closeDate.addDays(7));
    }

    @isTest
    static void insertNonWonChangesNothing() {
        Account a = makeAccount('Non Won Insert Account', 'Warm');
        Opportunity o = makeOpp('Non Won Insert Opp', 'Prospecting', Date.today().addDays(5), a.Id);

        Test.startTest();
        insert o;
        Test.stopTest();

        System.assertEquals(null, [SELECT NextStep FROM Opportunity WHERE Id = :o.Id].NextStep, 'NextStep must not be set for a non-won insert');
        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :o.Id], 'No task must be created for a non-won insert');
        System.assertEquals('Warm', [SELECT Rating FROM Account WHERE Id = :a.Id].Rating, 'Account rating must not change');
    }

    // ---------------------------------------------------------------------
    // Update into won
    // ---------------------------------------------------------------------

    @isTest
    static void updateToWonSetsNextStepCreatesTaskAndRatesAccount() {
        Account a = makeAccount('Update Won Account', 'Warm');
