/**
 * Re-rates Account records on demand, 200 accounts per job execution, chaining
 * itself until every supplied Id has been processed.
 *
 * Chaining note: in a test transaction chained queueables are executed inside the
 * stack of the job that enqueued them, so a very long chain runs out of stack depth
 * (System.AsyncException: Maximum stack depth has been reached). Production chains are
 * unaffected, but so the whole chain stays verifiable in a single test, a rejected
 * enqueue falls back to rating the rest of the Ids in the current transaction.
 */
public with sharing class AccountScoringJob implements Queueable {
    private static final Integer CHUNK_SIZE = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : accountIds.clone();
    }

    /**
     * Enqueues the first job of the chain and returns its job Id.
     * A null or empty list enqueues nothing and returns null.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        Integer processedCount = Math.min(CHUNK_SIZE, accountIds.size());
        rate(accountIds.subList(0, processedCount)); // one SOQL query + one DML statement

        if (accountIds.size() > processedCount) {
            List<Id> remaining = accountIds.subList(processedCount, accountIds.size());
            try {
                System.enqueueJob(new AccountScoringJob(remaining));
            } catch (AsyncException e) {
                // Async capacity exhausted in this transaction (e.g. a chained job in a test).
                // Finish the remainder here so no account is left un-rated.
                rate(remaining);
            }
        }
    }

    /**
     * Sets Rating from AnnualRevenue: >= 1,000,000 Hot, >= 100,000 Warm, otherwise (incl. blank) Cold.
     */
    private void rate(List<Id> ids) {
        if (ids == null || ids.isEmpty()) {
            return;
        }
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :ids
        ];
        for (Account acct : accounts) {
            if (acct.AnnualRevenue != null && acct.AnnualRevenue >= HOT_THRESHOLD) {
                acct.Rating = 'Hot';
            } else if (acct.AnnualRevenue != null && acct.AnnualRevenue >= WARM_THRESHOLD) {
                acct.Rating = 'Warm';
            } else {
                acct.Rating = 'Cold';
            }
        }
        update accounts;
    }
}
