        IBillingGateway gatewayMock = mockBillingGateway();

        Id firstAccount = fflib_IDGenerator.generate(Account.SObjectType);
        Id secondAccount = fflib_IDGenerator.generate(Account.SObjectType);
        Id ignoredAccount = fflib_IDGenerator.generate(Account.SObjectType);

        Opportunity wonOne = opportunity(firstAccount, CLOSED_WON, 100.00);
        Opportunity wonTwo = opportunity(secondAccount, CLOSED_WON, 250.50);
        Opportunity stillOpen = opportunity(ignoredAccount, 'Prospecting', 500.00);
        Opportunity zeroAmount = opportunity(ignoredAccount, CLOSED_WON, 0);
        Opportunity nullAmount = opportunity(ignoredAccount, CLOSED_WON, null);

        Set<Id> opportunityIds = new Set<Id>{
            wonOne.Id, wonTwo.Id, stillOpen.Id, zeroAmount.Id, nullAmount.Id
        };

        mocks.when(selectorMock.selectById(opportunityIds))
            .thenReturn(new List<Opportunity>{ wonOne, wonTwo, stillOpen, zeroAmount, nullAmount });
        mocks.when(gatewayMock.createInvoice(firstAccount, wonOne.Amount)).thenReturn('INV-001');
        mocks.when(gatewayMock.createInvoice(secondAccount, wonTwo.Amount)).thenReturn('INV-002');

        Integer invoiced;

        Test.startTest();
        invoiced = InvoicingService.invoiceWonOpportunities(opportunityIds);
        Test.stopTest();

        System.assertEquals(2, invoiced, 'Only the two qualifying opportunities should be invoiced');

        System.assertEquals('Invoiced: INV-001', wonOne.NextStep, 'NextStep must carry the invoice number');
        System.assertEquals('Invoiced: INV-002', wonTwo.NextStep, 'NextStep must carry the invoice number');
        System.assertEquals(null, stillOpen.NextStep, 'Open opportunities must not be touched');
        System.assertEquals(null, zeroAmount.NextStep, 'Zero amount opportunities must not be touched');
        System.assertEquals(null, nullAmount.NextStep, 'Null amount opportunities must not be touched');

        // The gateway is authenticated once and invoices exactly the qualifying opportunities.
