        verifyCreateInvoice(gatewayMock, firstAccount, wonOne.Amount, 1);
        verifyCreateInvoice(gatewayMock, secondAccount, wonTwo.Amount, 1);
        verifyCreateInvoice(gatewayMock, ignoredAccount, stillOpen.Amount, 0);

        // Non qualifying opportunities are neither invoiced nor registered.
        verifyRegisterDirty(stillOpen, 0);
        verifyRegisterDirty(zeroAmount, 0);
        verifyRegisterDirty(nullAmount, 0);

        // Every invoiced opportunity is registered as dirty and the work is committed once.
        verifyRegisterDirty(wonOne, 1);
        verifyRegisterDirty(wonTwo, 1);
        verifyCommitWork(1);
