    /**
     * Hand rolled, callout free billing gateway used where the double has to throw a
     * BillingException (ApexMocks can only stub methods that return a value).
     */
    private class BillingGatewayStub implements IBillingGateway {

        private BillingException authenticationFailure;
        private Map<Id, BillingException> invoiceFailuresByAccountId;
        private Map<Id, String> invoiceNumbersByAccountId;

        public Integer authenticationCount { get; private set; }
        public List<Id> invoicedAccountIds { get; private set; }
        public List<Decimal> invoicedAmounts { get; private set; }

        public BillingGatewayStub() {
            this.invoiceFailuresByAccountId = new Map<Id, BillingException>();
            this.invoiceNumbersByAccountId = new Map<Id, String>();
            this.invoicedAccountIds = new List<Id>();
            this.invoicedAmounts = new List<Decimal>();
            this.authenticationCount = 0;
        }

        public BillingGatewayStub withAuthenticationFailure(String message) {
            this.authenticationFailure = new BillingException(message);
            return this;
        }

        public BillingGatewayStub withInvoiceNumber(Id accountId, String invoiceNumber) {
            this.invoiceNumbersByAccountId.put(accountId, invoiceNumber);
            return this;
        }

        public BillingGatewayStub withInvoiceFailure(Id accountId, String message) {
            this.invoiceFailuresByAccountId.put(accountId, new BillingException(message));
            return this;
        }

        public void authenticate() {
            this.authenticationCount++;
            if (this.authenticationFailure != null) {
                throw this.authenticationFailure;
            }
        }

        public String createInvoice(Id accountId, Decimal amount) {
            this.invoicedAccountIds.add(accountId);
            this.invoicedAmounts.add(amount);

            if (this.invoiceFailuresByAccountId.containsKey(accountId)) {
                throw this.invoiceFailuresByAccountId.get(accountId);
            }
            if (this.invoiceNumbersByAccountId.containsKey(accountId)) {
                return this.invoiceNumbersByAccountId.get(accountId);
            }
            return 'INV-' + this.invoicedAccountIds.size();
        }
    }
}
