@isTest
private class OpportunityForecastServiceTest {

    /**
     * The weighted amount is Amount * Probability / 100, rounded to 2 decimals
     * per opportunity, and then summed per StageName.
     *
     * 1.99 * 33 / 100 = 0.6567, which rounds to 0.66 per opportunity.
     * Three such opportunities give 1.98.
     * If the rounding were applied to the stage total instead, the total would be
     * 1.9701 -> 1.97, so this test fails if the rounding is not per opportunity.
     */
    @isTest
    static void sumsWeightedAmountsPerStageRoundingPerOpportunity() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, mockSelector);

        Id accountId1 = fflib_IDGenerator.generate(Account.SObjectType);
        Id accountId2 = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId1, accountId2 };

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountId1, 'Prospecting', 1.99, 33),
            buildOpportunity(accountId2, 'Prospecting', 1.99, 33),
            buildOpportunity(accountId1, 'Prospecting', 1.99, 33),
            // 100 * 50 / 100 = 50.00 (exact, no rounding needed)
            buildOpportunity(accountId2, 'Qualification', 100, 50),
            // 200 * 25 / 100 = 50.00
            buildOpportunity(accountId1, 'Qualification', 200, 25)
        };

        mocks.startStubbing();
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();

        Map<String, Decimal> result =
            OpportunityForecastService.weightedAmountByStage(accountIds);

        System.assertEquals(2, result.size(), 'Expected one total per StageName');
        assertDecimalEquals(
            Decimal.valueOf('1.98'),
            result.get('Prospecting'),
            'Prospecting total must sum the per-opportunity rounded weights (0.66 * 3)'
        );
        assertDecimalEquals(
            Decimal.valueOf('100.00'),
            result.get('Qualification'),
            'Qualification total must sum 50.00 + 50.00'
        );

        ((IOpportunitiesSelector) mocks.verify(mockSelector, 1))
            .selectOpenByAccountIds(accountIds);
    }

    /**
     * Opportunities with a null Amount or a null Probability are ignored
     * (they must not add anything to any stage).
     */
