            buildOpportunity(accountId, 'Negotiation', 500, null)
        };

        mocks.startStubbing();
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();

        Map<String, Decimal> result =
            OpportunityForecastService.weightedAmountByStage(accountIds);

        System.assertEquals(
            1,
            result.size(),
            'Only the complete opportunity may contribute, so only one stage must be present'
        );
        System.assertEquals(
