            .thenReturn(opportunitiesIfQueried);
        mocks.stopStubbing();

        Map<String, Decimal> result =
            OpportunityForecastService.weightedAmountByStage(accountIds);

        System.assertNotEquals(null, result, 'The result must never be null');
        System.assertEquals(
            0,
            result.size(),
            'Empty account ids must return an empty map without querying the selector'
        );
    }

    private static Opportunity buildOpportunity(
        Id accountId,
        String stageName,
        Decimal amount,
        Decimal probability
    ) {
        Opportunity opp = new Opportunity(
            Name = 'Test Opportunity',
            AccountId = accountId,
            StageName = stageName,
            CloseDate = Date.today().addDays(30)
        );
        opp.Id = fflib_IDGenerator.generate(Opportunity.SObjectType);
        opp.Amount = amount;
        opp.Probability = probability;
        return opp;
    }

    /**
     * Numeric comparison that is independent of the Decimal scale
     * (1.98 vs 1.980000 etc. must both pass).
     */
    private static void assertDecimalEquals(Decimal expected, Decimal actual, String message) {
        System.assertNotEquals(null, actual, message + ' - the value was missing from the map');
        Decimal difference = actual - expected;
        System.assert(
            difference.abs() < 0.0001,
            message + ' - expected ' + expected + ' but was ' + actual
        );
    }
