public with sharing class Opportunities extends fflib_SObjectDomain {
    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onAfterInsert() {
        Set<Id> opportunityIds = new Set<Id>();

        for (Opportunity opportunity : (List<Opportunity>) Records) {
            if (opportunity.StageName == 'Closed Won') {
                opportunityIds.add(opportunity.Id);
            }
        }

        startFulfilmentIfNeeded(opportunityIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> opportunityIds = new Set<Id>();

        for (Opportunity opportunity : (List<Opportunity>) Records) {
            Opportunity oldOpportunity = (Opportunity) existingRecords.get(opportunity.Id);

            if (opportunity.StageName == 'Closed Won' &&
                oldOpportunity != null &&
                oldOpportunity.StageName != 'Closed Won') {
                opportunityIds.add(opportunity.Id);
            }
        }

