        validateAmountNotNegative();
        validateAmountUnchangedOnWon(existingRecords);
    }

    private void validateAmountNotNegative() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                addAmountError(opp, 'Amount cannot be negative.');
            }
        }
    }

    private void validateAmountUnchangedOnWon(Map<Id, SObject> existingRecords) {
        if (existingRecords == null) {
            return;
        }
        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (oldOpp != null
                && oldOpp.StageName == 'Closed Won'
                && opp.Amount != oldOpp.Amount) {
                addAmountError(opp, 'Amount cannot change on a won opportunity.');
            }
        }
    }

    private void addAmountError(Opportunity opp, String message) {
        // Record the error through the domain helper so it is captured in
        // fflib_SObjectDomain.Errors (used by unit tests).
        error(message, opp, Opportunity.Amount);

        // Add the field-level error to the offending record so DML fails for
        // that record only (bulk-safe, other records still save).
        if (Trigger.isExecuting) {
            opp.addError(Opportunity.Amount, message);
        }
    }
