/**
 * Account selector used by the credit team.
 *
 * - Selects Id, Name and Industry plus every field of the Credit_Review field set.
 *   The field set is read at runtime (Schema.SObjectType.Account.fieldSets.Credit_Review),
 *   so admins can add or remove fields without any code change.
 * - Every query is executed in user mode (WITH USER_MODE), so the platform enforces the
 *   running user's object, field and sharing access. A user who cannot read one of the
 *   selected fields receives a QueryException instead of data.
 * - The Contact subquery is built from the ContactsSelector's field list so both selectors
 *   stay in sync.
 */
public with sharing class AccountsSelector extends fflib_SObjectSelector {

    private static final String ACCOUNT_OBJECT_NAME = 'Account';
    private static final String CONTACT_RELATIONSHIP_NAME = 'Contacts';
    private static final String USER_MODE_CLAUSE = ' WITH USER_MODE';

    public AccountsSelector() {
        super();
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    public override List<Schema.FieldSet> getSObjectFieldSetList() {
        return new List<Schema.FieldSet>{
            Schema.SObjectType.Account.fieldSets.Credit_Review
        };
    }

    /**
     * Selects the accounts with the given ids (base fields + Credit_Review field set fields).
     */
    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        String soqlQuery =
            'SELECT ' + buildAccountFieldList()
            + ' FROM ' + ACCOUNT_OBJECT_NAME
            + ' WHERE Id IN :accountIds'
            + USER_MODE_CLAUSE;

        return (List<Account>) Database.query(soqlQuery);
    }

    /**
     * Selects the accounts with the given ids together with their Contacts child records.
     * The Contact subquery is derived from the ContactsSelector so it selects exactly the
     * fields that selector defines.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        String soqlQuery =
            'SELECT ' + buildAccountFieldList()
            + ', (' + buildContactSubquery() + ')'
            + ' FROM ' + ACCOUNT_OBJECT_NAME
            + ' WHERE Id IN :accountIds'
            + USER_MODE_CLAUSE;

        return (List<Account>) Database.query(soqlQuery);
    }

    /**
     * Builds the Account (top level) field list: selector fields plus every field of the
     * configured field sets, de-duplicated while preserving order.
     */
    private String buildAccountFieldList() {
        List<String> fieldPaths = new List<String>();
        Set<String> addedFieldPaths = new Set<String>();

        for (Schema.SObjectField accountField : getSObjectFieldList()) {
            addFieldPath(accountField.getDescribe().getName(), fieldPaths, addedFieldPaths);
        }

        for (Schema.FieldSet fieldSet : getSObjectFieldSetList()) {
            if (fieldSet == null) {
                continue;
            }
            for (Schema.FieldSetMember fieldSetMember : fieldSet.getFields()) {
                addFieldPath(fieldSetMember.getFieldPath(), fieldPaths, addedFieldPaths);
            }
        }

        return joinFieldPaths(fieldPaths);
    }

    /**
     * Builds the Contact subquery from the ContactsSelector's field list.
     */
    private String buildContactSubquery() {
        ContactsSelector contactsSelector = new ContactsSelector();

        List<String> fieldPaths = new List<String>();
        Set<String> addedFieldPaths = new Set<String>();

        for (Schema.SObjectField contactField : contactsSelector.getSObjectFieldList()) {
            addFieldPath(contactField.getDescribe().getName(), fieldPaths, addedFieldPaths);
        }

        return 'SELECT ' + joinFieldPaths(fieldPaths)
            + ' FROM ' + CONTACT_RELATIONSHIP_NAME;
    }

    private void addFieldPath(String fieldPath, List<String> fieldPaths, Set<String> addedFieldPaths) {
        if (String.isBlank(fieldPath)) {
            return;
        }
        String normalizedFieldPath = fieldPath.toLowerCase();
        if (addedFieldPaths.contains(normalizedFieldPath)) {
            return;
        }
        addedFieldPaths.add(normalizedFieldPath);
        fieldPaths.add(fieldPath);
    }

    private String joinFieldPaths(List<String> fieldPaths) {
        String joinedFieldPaths = '';
        for (String fieldPath : fieldPaths) {
            joinedFieldPaths += (String.isEmpty(joinedFieldPaths) ? '' : ', ') + fieldPath;
        }
        return joinedFieldPaths;
    }
}
