public with sharing class OpportunityWinService {
    private static final String CLOSED_WON = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName != CLOSED_WON) {
                opportunity.StageName = CLOSED_WON;
                opportunity.CloseDate = Date.today();
                opportunitiesToClose.add(opportunity);
            }
        }

        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        // One unit of work: the opportunity updates happen first, and the platform
        // events are published only after those DML operations have succeeded. Both
        // live in the same transaction, so if any DML fails the whole thing rolls
        // back (events included) and the exception propagates to the caller.
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        uow.registerDirty(opportunitiesToClose);

        List<SObject> eventsToPublish = new List<SObject>();
        for (Opportunity opportunity : opportunitiesToClose) {
            eventsToPublish.add(new Deal_Won__e(
                Opportunity_Id__c = opportunity.Id,
                Amount__c = opportunity.Amount
            ));
        }
        uow.registerPublishAfterTransaction(eventsToPublish);

        // Single commit.
        uow.commitWork();

        return opportunitiesToClose.size();
    }
}
