```apex
trigger CaseTrigger on Case (after update) {
    if (!Trigger.isAfter || !Trigger.isUpdate) {
        return;
    }

    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        if (oldCase == null) {
            continue;
        }

        // Not closed -> closed, and the customer can actually be surveyed.
        if (c.IsClosed && !oldCase.IsClosed && c.ContactId != null) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    if (newlyClosedCaseIds.isEmpty()) {
        return;
    }

    if (newlyClosedCaseIds.size() <= CaseSurveyJob.MAX_JOBS_PER_TRANSACTION) {
        // Normal agent bulk close: one Queueable per case, one transaction per case.
        for (Id caseId : newlyClosedCaseIds) {
            System.enqueueJob(new CaseSurveyJob(caseId));
        }
        return;
    }

    // Oversized close (e.g. up to 200 cases in one API transaction). A transaction
    // cannot enqueue more than 50 Queueables, and nesting async work (chained
    // Queueables / executeBatch from the trigger) is strictly limited in tests and
    // at runtime. Hand the whole set to a single bulk CaseSurveyJob instead.
    System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
}
