public with sharing class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult result = new ImportResult();
            result.success = false;
            results.add(result);
        }

        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        List<Integer> stagedIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];

            if (gift == null) {
                results[i].errorMessage = 'Gift is null.';
                continue;
            }

            npsp__DataImport__c dataImport = new npsp__DataImport__c();
            dataImport.npsp__Contact1_Firstname__c = gift.firstName;
            dataImport.npsp__Contact1_Lastname__c = gift.lastName;
            dataImport.npsp__Contact1_Personal_Email__c = gift.email;
            dataImport.npsp__Donation_Amount__c = gift.amount;
            dataImport.npsp__Donation_Date__c = gift.giftDate;
            dataImport.npsp__Donation_Donor__c = 'Contact1';

            staged.add(dataImport);
            stagedIndexes.add(i);
        }

        if (staged.isEmpty()) {
            return results;
        }

        Database.SaveResult[] insertResults = Database.insert(staged, false);

        List<npsp__DataImport__c> inserted = new List<npsp__DataImport__c>();
        List<Id> insertedIds = new List<Id>();
        Map<Id, Integer> idToResultIndex = new Map<Id, Integer>();

        for (Integer i = 0; i < insertResults.size(); i++) {
            Database.SaveResult saveResult = insertResults[i];
            Integer resultIndex = stagedIndexes[i];

            if (saveResult.isSuccess()) {
                Id dataImportId = saveResult.getId();
                insertedIds.add(dataImportId);
                idToResultIndex.put(dataImportId, resultIndex);
                inserted.add(staged[i]);
            } else {
                results[resultIndex].errorMessage = saveResult.getErrors()[0].getMessage();
            }
        }

        if (insertedIds.isEmpty()) {
            return results;
        }

        String engineError;
        try {
            npsp.BDI_DataImportService service = new npsp.BDI_DataImportService(false);
            service.processSave(inserted);
        } catch (Exception ex) {
            engineError = ex.getMessage();
        }

        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :insertedIds
        ]);

        for (Id dataImportId : insertedIds) {
            Integer resultIndex = idToResultIndex.get(dataImportId);
            npsp__DataImport__c dataImport = processed.get(dataImportId);

            if (dataImport == null) {
                if (String.isBlank(results[resultIndex].errorMessage)) {
                    results[resultIndex].errorMessage = String.isNotBlank(engineError)
                        ? engineError
                        : 'NPSP Data Import record was not processed.';
                }
                continue;
            }

            results[resultIndex].contactId = dataImport.npsp__Contact1Imported__c;
            results[resultIndex].opportunityId = dataImport.npsp__DonationImported__c;

            if (dataImport.npsp__Status__c == 'Imported') {
                results[resultIndex].success = true;
                results[resultIndex].errorMessage = null;
            } else {
                results[resultIndex].success = false;

                String message = dataImport.npsp__FailureInformation__c;
                if (String.isBlank(message)) {
                    message = String.isNotBlank(engineError)
                        ? engineError
                        : 'NPSP Data Import status: ' + dataImport.npsp__Status__c;
                }
                results[resultIndex].errorMessage = message;
            }
        }

        return results;
    }
}
