public with sharing class HouseholdService {
    /**
     * Creates ONE NPSP household account for the supplied (new) contacts and returns
     * that household's Id. The first contact becomes the household's primary contact.
     *
     * Strategy: insert the first contact on its own with no AccountId. With the
     * Household Account model, NPSP's household logic creates and names the household
     * account for that contact and records it as the primary contact
     * (npe01__One2OneContact__c). The remaining contacts are then inserted into that
     * same household. This guarantees exactly one household is created and that the
     * account name/greetings are generated by NPSP rather than hard-coded here.
     */
    public class HouseholdServiceException extends Exception {}

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact');
        }

        Savepoint savepoint = Database.setSavepoint();

        try {
            // Insert the primary contact first so NPSP creates, names and configures
            // the household account (record type HH_Account).
            Contact primaryContact = members[0];
            primaryContact.AccountId = null;
            insert primaryContact;

            Id householdId = primaryContact.AccountId;
            if (householdId == null) {
                throw new HouseholdServiceException(
                    'NPSP did not create a household account for the primary contact.'
                );
            }

            // Attach the remaining members to the same household.
            List<Contact> additionalMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i];
                member.AccountId = householdId;
                additionalMembers.add(member);
            }
            if (!additionalMembers.isEmpty()) {
                insert additionalMembers;
            }

            // Make sure the first contact is the household's primary contact
            // (idempotent: NPSP normally sets this already; the update also lets
            // NPSP (re)apply its naming/greeting logic).
            update new Account(
                Id = householdId,
                npe01__One2OneContact__c = primaryContact.Id
            );

            return householdId;
        } catch (Exception ex) {
            Database.rollback(savepoint);
            throw ex;
        }
    }
}
