/**
 * OPP_MajorGiftFollowUp_TDTM
 *
 * TDTM (Table-Driven Trigger Management) handler for NPSP.
 *
 * Registered by the admin under NPSP Settings > Trigger Configuration:
 *   Class          : OPP_MajorGiftFollowUp_TDTM
 *   Object         : Opportunity
 *   Trigger Action : AfterInsert;AfterUpdate
 *   Load Order     : 5
 *   Asynchronous   : No
 *
 * Behaviour:
 *   - On insert: when the Opportunity is Closed Won with Amount >= 5000.
 *   - On update: only when the Opportunity newly becomes Closed Won with
 *     Amount >= 5000 (it was not both Closed Won and >= 5000 before).
 *   - Creates exactly one Task: "Major gift thank-you call", Priority High,
 *     Status Not Started, WhatId = Opportunity, WhoId = npsp__Primary_Contact__c,
 *     OwnerId = Opportunity owner, ActivityDate = CloseDate + 3 days.
 *
 * Bulk safe: no SOQL, a single DML insert for up to 200 Opportunities.
 * The handler only runs when the TDTM Trigger Handler record is active.
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer FOLLOW_UP_DAYS = 3;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        // Only act on after-insert and after-update.
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);
        Integer recordCount = newlist.size();
        Integer oldCount = (oldlist == null) ? 0 : oldlist.size();

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < recordCount; i++) {
            SObject newRecord = newlist[i];

            // Only process Opportunity records.
            if (newRecord == null
                || newRecord.getSObjectType() != Opportunity.SObjectType) {
                continue;
            }

            Opportunity newOpp = (Opportunity) newRecord;

            // Must be a qualifying major gift now.
            if (!isQualifyingMajorGift(newOpp)) {
                continue;
            }

            // On update, skip records that already qualified before.
            if (!isInsert
                && i < oldCount
                && oldlist[i] != null
                && oldlist[i].getSObjectType() == Opportunity.SObjectType
                && isQualifyingMajorGift((Opportunity) oldlist[i])) {
                continue;
            }

            tasksToInsert.add(buildFollowUpTask(newOpp));
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    /**
     * True when the Opportunity is Closed Won with an Amount of at least the
     * major gift threshold.
     */
    private static Boolean isQualifyingMajorGift(Opportunity opp) {
        return opp != null
            && opp.StageName == CLOSED_WON_STAGE
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    /**
     * Builds the major gift follow-up Task for a qualifying Opportunity.
     */
    private static Task buildFollowUpTask(Opportunity opp) {
        Task followUp = new Task();
        followUp.Subject = TASK_SUBJECT;
        followUp.Priority = TASK_PRIORITY;
        followUp.Status = TASK_STATUS;
        followUp.WhatId = opp.Id;
        followUp.WhoId = opp.npsp__Primary_Contact__c;
        followUp.OwnerId = opp.OwnerId;

        if (opp.CloseDate != null) {
            followUp.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_DAYS);
        }

        return followUp;
    }
}
