public with sharing class EmployeeDirectoryService {
    private static final List<String> OPTIONAL_FIELDS = new List<String>{
        'Department__c',
        'Salary__c',
        'Personal_Email__c'
    };

    public static List<FB_Employee__c> getDirectory() {
        // Resolve the object defensively and return nothing if the running user
        // has no read access at the object level (sharing is still enforced by
        // the `with sharing` keyword on the class).
        Schema.SObjectType employeeType = Schema.getGlobalDescribe().get('FB_Employee__c');
        if (employeeType == null) {
            return new List<FB_Employee__c>();
        }

        Schema.DescribeSObjectResult employeeDescribe = employeeType.getDescribe();
        if (!employeeDescribe.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Only select custom fields that actually exist on the object, so the
        // query never fails on a missing column.
        Set<String> availableFieldNames = new Set<String>();
        for (String fieldKey : employeeDescribe.fields.keySet()) {
            availableFieldNames.add(fieldKey.toLowerCase());
        }

        List<String> selectedFields = new List<String>{ 'Id', 'Name' };
        for (String fieldName : OPTIONAL_FIELDS) {
            if (availableFieldNames.contains(fieldName.toLowerCase())) {
                selectedFields.add(fieldName);
            }
        }

        String soql = 'SELECT ' + String.join(selectedFields, ', ')
            + ' FROM FB_Employee__c ORDER BY Name ASC';

        List<FB_Employee__c> employees;
        try {
            employees = (List<FB_Employee__c>) Database.query(soql);
        } catch (QueryException e) {
            // Last-resort fallback: never return fields that cannot be queried.
            employees = [SELECT Id, Name FROM FB_Employee__c ORDER BY Name ASC];
        }

        // Remove any field the running user cannot read. Unreadable fields are
        // omitted from the returned records entirely (not returned as null).
        SObjectAccessDecision decision = Security.stripInaccessible(
            AccessType.READABLE,
            employees
        );

        return (List<FB_Employee__c>) decision.getRecords();
    }
}
